/// The Unix time this image was built at.
///
/// A Pico has no RTC on the chip, so a software clock has to start somewhere. The extension writes
/// the build's own time into `.cargo/config.toml` before every build, which makes "set when it was
/// flashed" true to the second the compiler started -- and on a W board the network corrects it.
#[allow(dead_code)]
const BUILD_EPOCH: i64 = match option_env!("RUSTY_EPOCH") {
    Some(text) => match parse_i64(text) {
        Some(value) => value,
        None => 0,
    },
    None => 0,
};

/// Minutes to add to UTC to get the time on the glass. Written by the project wizard; edit it when the
/// clocks change, because a `no_std` image has no timezone database.
#[allow(dead_code)]
pub const UTC_OFFSET_MINUTES: i64 = 0;

/// Parses a signed decimal number, or nothing: the value is a build-time string, so a typo has to read
/// as "no time yet" rather than as a panic.
#[allow(dead_code)]
const fn parse_i64(text: &str) -> Option<i64> {
    let bytes = text.as_bytes();
    if bytes.is_empty() {
        return None;
    }
    let (negative, digits) = match bytes[0] {
        b'-' => (true, 1),
        b'+' => (false, 1),
        _ => (false, 0),
    };
    if digits >= bytes.len() {
        return None;
    }
    let mut value: i64 = 0;
    let mut index = digits;
    while index < bytes.len() {
        let byte = bytes[index];
        if byte < b'0' || byte > b'9' {
            return None;
        }
        value = value * 10 + (byte - b'0') as i64;
        index += 1;
    }
    Some(if negative { -value } else { value })
}

/// The civil date `days` days after 1970-01-01 (Howard Hinnant's civil_from_days).
///
/// Integer arithmetic only, no std and no timezone database, because a date block on a Pico has
/// nothing else to read the calendar from.
#[allow(dead_code)]
pub fn civil_from_days(days: i64) -> (u16, u8, u8) {
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 157_908) / 365;
    let mut year = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let month_day = (5 * doy + 2) / 153;
    let day = (doy - (153 * month_day + 2) / 5 + 1) as u8;
    let month = if month_day < 10 { month_day + 3 } else { month_day - 9 } as u8;
    if month <= 2 {
        year += 1;
    }
    (year as u16, month, day)
}

/// The wall clock the firmware starts from: the build's own date and time, in local time.
///
/// This is the firmware's RTC seed on a board with no chip RTC: the extension writes the build's
/// Unix timestamp into `.cargo/config.toml` before every build, and a W board's SNTP answer
/// replaces it once the network answers.
#[allow(dead_code)]
pub fn boot_datetime() -> (u16, u8, u8, u8, u8, u8) {
    let seconds = BUILD_EPOCH + UTC_OFFSET_MINUTES * 60;
    let days = seconds.div_euclid(86_400);
    let of_day = seconds.rem_euclid(86_400);
    let (year, month, day) = civil_from_days(days);
    (
        year,
        month,
        day,
        (of_day / 3_600) as u8,
        ((of_day % 3_600) / 60) as u8,
        (of_day % 60) as u8,
    )
}

